from collections import Counter

def diag(grid):
 h,w=len(grid),len(grid[0]); colors=set(sum(grid,[]))
 def inds(axis,col):
  n=h if axis=='r' else w; m=w if axis=='r' else h
  return [i for i in range(n) if (grid[i].count(col) if axis=='r' else sum(grid[r][i]==col for r in range(h))) / m >= .6]
 def step(ix):
  if len(ix)<2:return None
  gaps=[b-a for a,b in zip(ix,ix[1:])]; st=Counter(gaps).most_common(1)[0][0]
  return st if st>=2 and gaps.count(st)/len(gaps)>=.8 else None
 return {c:(inds('r',c),step(inds('r',c)),inds('c',c),step(inds('c',c))) for c in colors}
print(diag(grid))
